/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

/**
 * The status groups the filter vocabulary accepts alongside the six
 * statuses themselves (ADR 0009). `open` is "not closed", not an
 * independent list, so it can never drift from `CLOSED_ISSUE_STATUSES`.
 */
export const ISSUE_STATUS_GROUPS = {
  open: ISSUE_STATUSES.filter(
    (status) => !CLOSED_ISSUE_STATUSES.includes(status),
  ),
  closed: CLOSED_ISSUE_STATUSES,
} as const satisfies Record<string, readonly IssueStatus[]>;

export type IssueStatusGroup = keyof typeof ISSUE_STATUS_GROUPS;

export const ISSUE_STATUS_GROUP_NAMES: readonly IssueStatusGroup[] = [
  "open",
  "closed",
];

/** A value the status filter accepts: one status, or one of its groups. */
export type IssueStatusFilterValue = IssueStatus | IssueStatusGroup;

function isIssueStatusGroup(value: string): value is IssueStatusGroup {
  return (ISSUE_STATUS_GROUP_NAMES as readonly string[]).includes(value);
}

/** Expands a mix of statuses and group names into the plain statuses they
 *  mean, de-duplicated. Used wherever a status filter is actually read, so
 *  `status=open` means the same thing on every entry point. */
export function expandIssueStatusFilter(
  values: readonly string[],
): readonly IssueStatus[] {
  const expanded = new Set<IssueStatus>();
  for (const value of values) {
    if (isIssueStatusGroup(value)) {
      for (const status of ISSUE_STATUS_GROUPS[value]) expanded.add(status);
    } else if ((ISSUE_STATUSES as readonly string[]).includes(value)) {
      expanded.add(value as IssueStatus);
    }
  }
  return [...expanded];
}

