 *  a page asking for `assignee=me` / `author=me` get the same answer
 *  (ADR 0009 #2). The repository never sees the literal `"me"`. */
function resolveMe(actor: Actor, input: IssueFilterInput): IssueFilterInput {
  return {
    ...input,
    ...(input.assigneeId === "me"
      ? { assigneeId: actor.userId }
      : {}),
    ...(input.authorId === "me" ? { authorId: actor.userId } : {}),
  };
}

export async function listIssues(
  actor: Actor,
  input: IssueFilterInput,
): Promise<Page<Issue>> {
  assertOrgScope(actor, input.orgId);
  // A cross-project list is an org-wide read; per-project visibility is
  // enforced when the caller opens an individual issue.
  assertCan(actor, "issue:read", orgResource(input.orgId));
  return issueRepo.listIssues(resolveMe(actor, input));
}

