/** Adapts the awaited `searchParams` record to the `.get()` shape the shared
 *  filter codec expects, so this page reads the URL the same way the filter
 *  bar writes it (ADR 0009 #1) instead of re-parsing it by hand. */
function readableSearchParams(
  search: Record<string, string | string[] | undefined>,
): ReadableParams {
  return {
    get(name: string): string | null {
      const value = search[name];
      if (Array.isArray(value)) return value[0] ?? null;
      return value ?? null;
    },
  };
}

